import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"हर किसी के लिए पथ गारंटी प्रणाली","description":"","frontmatter":{},"headers":[],"relativePath":"hi/08-人人有路保障体系.md","filePath":"hi/08-人人有路保障体系.md"}'),i={name:"hi/08-人人有路保障体系.md"};function d(l,t,h,n,s,u){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="हर-किसी-के-लिए-पथ-गारंटी-प्रणाली" tabindex="-1">हर किसी के लिए पथ गारंटी प्रणाली <a class="header-anchor" href="#हर-किसी-के-लिए-पथ-गारंटी-प्रणाली" aria-label="Permalink to &quot;हर किसी के लिए पथ गारंटी प्रणाली&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>08</td></tr><tr><td>मॉड्यूल</td><td>सामान्य सिद्धांत और मूल सेटिंग्स</td></tr><tr><td>कीवर्ड</td><td>हर किसी के लिए पथ, गारंटी प्रणाली, विकास-न्यूनतम रेखा, वंचित समूह, सर्व-कल्याण</td></tr></tbody></table><h2 id="i-हर-किसी-के-लिए-पथ-की-मूल-परिभाषा" tabindex="-1">I. हर किसी के लिए पथ की मूल परिभाषा <a class="header-anchor" href="#i-हर-किसी-के-लिए-पथ-की-मूल-परिभाषा" aria-label="Permalink to &quot;I. हर किसी के लिए पथ की मूल परिभाषा&quot;">​</a></h2><p>हर किसी के लिए पथ लंगर सहजीवी सभ्यता के केंद्रीय सामाजिक लक्ष्यों में से एक है: यह सुनिश्चित करना कि हेंग युआनझोउ का हर जीवन — चाहे उसकी जाति, उत्पत्ति, दान, स्तर या धन-स्थिति कुछ भी हो — अपने अनुरूप विकास पथ प्राप्त कर सके, और उसे अपने प्रयासों से स्तर-उन्नति और जीवन-परिपूर्णता प्राप्त करने का अवसर मिले। &quot;पथ होना&quot; का अर्थ केवल सीखने योग्य साधना विधियाँ नहीं, बल्कि उपयोग योग्य संसाधन, पूछने योग्य गुरु, साधना योग्य वातावरण और भरोसा करने योग्य संस्थाएँ भी हैं।</p><p>हर किसी के लिए पथ और अधिक परिश्रम-अधिक प्रतिफल सहजीवी सभ्यता की वितरण प्रणाली के दो स्तंभ हैं। अधिक परिश्रम-अधिक प्रतिफल &quot;दक्षता&quot; की समस्या हल करता है, शक्तिशालियों को अधिक मूल्य सृजित करने की प्रेरणा देता है; हर किसी के लिए पथ &quot;न्याय&quot; की समस्या हल करता है, यह सुनिश्चित करता है कि कमजोरों को विकास प्रणाली द्वारा त्यागा न जाए। दोनों परस्पर पूरक हैं, एक के बिना दूसरा अधूरा। हर किसी के लिए पथ के बिना, अधिक परिश्रम-अधिक प्रतिफल वन-नियम में पतित हो जाएगा; अधिक परिश्रम-अधिक प्रतिफल के बिना, हर किसी के लिए पथ समतावाद में पतित हो जाएगा।</p><h2 id="ii-हर-किसी-के-लिए-पथ-की-आवश्यकता" tabindex="-1">II. हर किसी के लिए पथ की आवश्यकता <a class="header-anchor" href="#ii-हर-किसी-के-लिए-पथ-की-आवश्यकता" aria-label="Permalink to &quot;II. हर किसी के लिए पथ की आवश्यकता&quot;">​</a></h2><p>गारंटी प्रणाली की स्थापना निम्नलिखित गहरी समझ पर आधारित है:</p><h3 id="_2-1-विकास-अधिकार-सबसे-मौलिक-जीवन-अधिकार-है" tabindex="-1">2.1 विकास-अधिकार सबसे मौलिक जीवन-अधिकार है <a class="header-anchor" href="#_2-1-विकास-अधिकार-सबसे-मौलिक-जीवन-अधिकार-है" aria-label="Permalink to &quot;2.1 विकास-अधिकार सबसे मौलिक जीवन-अधिकार है&quot;">​</a></h3><p>साधना सभ्यताओं में, विकास-अधिकार केवल विकास-अधिकार नहीं, बल्कि जीवन-अधिकार भी है। ब्रह्मांड की विभिन्न खतरनाक परिस्थितियों (जैसे विमान-उतारचढ़ाव, ऊर्जा-तूफान, विदेशी जातियों का आक्रमण) में, निम्न स्तर वाले जीवन की जीवित रहने की संभावना उच्च स्तर वाले जीवन से कहीं कम होती है। इसलिए, हर जीवन के विकास पथ की गारंटी अनिवार्य रूप से हर जीवन के मूल जीवन-अधिकार की गारंटी है।</p><h3 id="_2-2-प्रारंभिक-दान-के-अंतर-विकास-का-भाग्य-निर्धारित-नहीं-करने-चाहिए" tabindex="-1">2.2 प्रारंभिक दान के अंतर विकास का भाग्य निर्धारित नहीं करने चाहिए <a class="header-anchor" href="#_2-2-प्रारंभिक-दान-के-अंतर-विकास-का-भाग्य-निर्धारित-नहीं-करने-चाहिए" aria-label="Permalink to &quot;2.2 प्रारंभिक दान के अंतर विकास का भाग्य निर्धारित नहीं करने चाहिए&quot;">​</a></h3><p>हर जीवन के प्रारंभिक दान (जातीय प्रतिभा, पारिवारिक पृष्ठभूमि, जन्म-विमान, जन्मजात योग्यता आदि) में विशाल अंतर होते हैं। शिकारवाद के युग में, ये अंतर प्रायः अगम्य खाई में बदल जाते थे — अच्छे परिवारों के जीवन उच्च-गुणवत्ता संसाधनों का एकाधिकार करते थे, जबकि निम्न परिवारों के जीवन मूल साधना विधियाँ भी प्राप्त नहीं कर पाते थे। सहजीवी सभ्यता मानती है कि प्रारंभिक दान के अंतर वस्तुगत रूप से विद्यमान हैं, पर विकास भाग्य का एकमात्र निर्धारक नहीं बनने चाहिए। संस्थाओं की भूमिका इन प्रारंभिक अंतरों की भरपाई करना है, ताकि हर जीवन को परवर्ती प्रयासों से भाग्य बदलने का अवसर मिले।</p><h3 id="_2-3-त्यागे-गए-व्यक्ति-सभ्यता-की-संभावित-हानि-हैं" tabindex="-1">2.3 त्यागे गए व्यक्ति सभ्यता की संभावित हानि हैं <a class="header-anchor" href="#_2-3-त्यागे-गए-व्यक्ति-सभ्यता-की-संभावित-हानि-हैं" aria-label="Permalink to &quot;2.3 त्यागे गए व्यक्ति सभ्यता की संभावित हानि हैं&quot;">​</a></h3><p>हर जीवन में विकास क्षमता होती है; कई के पास केवल उपयुक्त पथ और संसाधनों की कमी होती है। तल पर संघर्ष करता जीवन उपयुक्त साधना प्रणाली पाने के बाद अद्भुत प्रतिभा दिखा सकता है; &quot;निकम्मा&quot; माना गया व्यक्ति शायद केवल अपने अनुरूप विकास दिशा नहीं खोज पाया। हर किसी के लिए पथ गारंटी प्रणाली का महत्व यह है कि वह किसी भी संभावित विकासकर्ता का परित्याग नहीं करती, सभ्यता के प्रतिभा-भंडार को यथासंभव विस्तृत करती है।</p><h3 id="_2-4-सार्वभौमिक-विकास-ब्रह्मांडीय-उन्नति-का-आधार-है" tabindex="-1">2.4 सार्वभौमिक विकास ब्रह्मांडीय उन्नति का आधार है <a class="header-anchor" href="#_2-4-सार्वभौमिक-विकास-ब्रह्मांडीय-उन्नति-का-आधार-है" aria-label="Permalink to &quot;2.4 सार्वभौमिक विकास ब्रह्मांडीय उन्नति का आधार है&quot;">​</a></h3><p>ब्रह्मांड की समग्र उन्नति केवल कुछ परम शक्तिशालियों पर निर्भर नहीं हो सकती, बल्कि दस हजार जातियों और सभी प्राणियों के सार्वभौमिक विकास की आवश्यकता है। लंगर जाल की दक्षता उससे जुड़े जीवनों की संख्या और गुणवत्ता से सकारात्मक रूप से संबंधित है। जब अधिक जीवन साधना प्रणालियों से जुड़कर स्तर बढ़ाते हैं, तो पूरे लंगर जाल का ऊर्जा संचार और नियम संचालन अधिक स्थिर और कुशल हो जाता है, और ब्रह्मांडीय उन्नति की प्रक्रिया तेज़ हो जाती है।</p><h2 id="iii-गारंटी-प्रणाली-की-पदानुक्रमित-संरचना" tabindex="-1">III. गारंटी प्रणाली की पदानुक्रमित संरचना <a class="header-anchor" href="#iii-गारंटी-प्रणाली-की-पदानुक्रमित-संरचना" aria-label="Permalink to &quot;III. गारंटी प्रणाली की पदानुक्रमित संरचना&quot;">​</a></h2><p>हर किसी के लिए पथ गारंटी प्रणाली चार स्तरों में विभाजित है, जो आधार से उन्नत तक पूर्ण गारंटी श्रृंखला बनाती है:</p><table tabindex="0"><thead><tr><th>स्तर</th><th>नाम</th><th>गारंटी सामग्री</th><th>कवरेज</th></tr></thead><tbody><tr><td>पहला स्तर</td><td>मूल गारंटी</td><td>निःशुल्क साधना विधियाँ, न्यूनतम संसाधन आवंटन, मूल चिकित्सा-शिक्षा</td><td>सभी जीवन, बिना शर्त</td></tr><tr><td>दूसरा स्तर</td><td>लक्षित सहायता</td><td>वंचित समूहों के लिए अतिरिक्त संसाधन, गुरु, तकनीकी समर्थन</td><td>प्रारंभिक दान में कमज़ोर व्यक्ति और जातियाँ</td></tr><tr><td>तीसरा स्तर</td><td>अवसर-विस्तार</td><td>उन्नत साधना अवसर, अंतर-विमान आदान-प्रदान, विशेष परियोजना भागीदारी अधिकार</td><td>क्षमता वाले पर संसाधन-वंचित साधक</td></tr><tr><td>चौथा स्तर</td><td>उपलब्धि-प्रोत्साहन</td><td>उच्च-स्तरीय संसाधन, लंगर उन्नत अभिगम, सभ्यता-सम्मान</td><td>उत्कृष्ट योगदान करने वाले साधक</td></tr></tbody></table><p>पहला स्तर &quot;तल-पकड़&quot; है, सुनिश्चित करता है कि कोई त्यागा न जाए; दूसरा &quot;अंतर-भरपाई&quot; है, प्रारंभिक दान के अंतर पूरा करता है; तीसरा &quot;सर्वोत्तम-पोषण&quot; है, क्षमता वाले व्यक्तियों को अधिक अवसर देता है; चौथा &quot;प्रोत्साहन&quot; है, उत्कृष्ट योगदानकर्ताओं को पुरस्कृत करता है। चार स्तर क्रमशः आगे बढ़ते हैं, पूर्ण गारंटी और प्रोत्साहन प्रणाली बनाते हैं।</p><h2 id="iv-मूल-गारंटी-की-विशिष्ट-सामग्री" tabindex="-1">IV. मूल गारंटी की विशिष्ट सामग्री <a class="header-anchor" href="#iv-मूल-गारंटी-की-विशिष्ट-सामग्री" aria-label="Permalink to &quot;IV. मूल गारंटी की विशिष्ट सामग्री&quot;">​</a></h2><p>मूल गारंटी हर किसी के लिए पथ प्रणाली का केंद्र है, जिसमें निम्नलिखित शामिल हैं:</p><h3 id="_4-1-साधना-विधि-गारंटी" tabindex="-1">4.1 साधना विधि गारंटी <a class="header-anchor" href="#_4-1-साधना-विधि-गारंटी" aria-label="Permalink to &quot;4.1 साधना विधि गारंटी&quot;">​</a></h3><p>तीन सौ मूल साधना प्रणालियों की मूल विधियाँ सभी जीवनों के लिए निःशुल्क खुली हैं, बिना किसी शर्त के। हर जीवन अपने अनुरूप साधना प्रणाली स्वतंत्र रूप से चुन सकता है — बिना शुल्क, बिना किसी विशिष्ट संप्रदाय में शामिल हुए, बिना योग्यता परीक्षा के। लंगर जाल प्रणाली-संगतता मूल्यांकन प्रदान करता है, साधकों को सबसे उपयुक्त पथ खोजने में मदद करता है।</p><h3 id="_4-2-साधना-संसाधन-गारंटी" tabindex="-1">4.2 साधना संसाधन गारंटी <a class="header-anchor" href="#_4-2-साधना-संसाधन-गारंटी" aria-label="Permalink to &quot;4.2 साधना संसाधन गारंटी&quot;">​</a></h3><p>उत्पादन-आधारित अनुबंध प्रणाली और सार्वजनिक संसाधन आवंटन के माध्यम से, हर जीवन को मूल साधना हेतु आवश्यक संसाधन मिलते हैं। मूल संसाधन आवंटन में शामिल: न्यूनतम ऊर्जा आपूर्ति, मूल साधना गोलियाँ, सामान्य साधना उपकरण उपयोग अधिकार। संसाधन-वंचित विमानों के लिए, लंगर जाल के माध्यम से अंतर-विमान संसाधन समायोजन होता है।</p><h3 id="_4-3-साधना-वातावरण-गारंटी" tabindex="-1">4.3 साधना वातावरण गारंटी <a class="header-anchor" href="#_4-3-साधना-वातावरण-गारंटी" aria-label="Permalink to &quot;4.3 साधना वातावरण गारंटी&quot;">​</a></h3><p>सभ्यता ने हर ग्रह और विमान पर सार्वजनिक साधना स्थल बनाए हैं, जिनमें सार्वजनिक साधना कक्ष, ऊर्जा-सांद्रता समायोजन क्षेत्र, नियम-अनुभूति कक्ष आदि शामिल हैं। ये स्थल सभी जीवनों के लिए निःशुल्क या कम मूल्य पर खुले हैं, यह सुनिश्चित करते हुए कि सबसे निर्धन साधक के पास भी उपयुक्त साधना वातावरण हो।</p><h3 id="_4-4-गुरु-मार्गदर्शन-गारंटी" tabindex="-1">4.4 गुरु मार्गदर्शन गारंटी <a class="header-anchor" href="#_4-4-गुरु-मार्गदर्शन-गारंटी" aria-label="Permalink to &quot;4.4 गुरु मार्गदर्शन गारंटी&quot;">​</a></h3><p>अंतर-जातीय गुरु जाल स्थापित करना, जिसमें उन्नत साधकों का कर्तव्य है कि वे कनिष्ठ साधकों को मूल मार्गदर्शन दें। हर कनिष्ठ साधक लंगर जाल के माध्यम से गुरु-मिलान आवेदन कर सकता है, और निःशुल्क मूल प्रश्न-उत्तर और साधना सुझाव प्राप्त कर सकता है। विशेष कठिनाइयों वाले साधकों के लिए, एक-से-एक लक्षित मार्गदर्शन दिया जाता है।</p><h3 id="_4-5-चिकित्सा-पुनर्वास-गारंटी" tabindex="-1">4.5 चिकित्सा पुनर्वास गारंटी <a class="header-anchor" href="#_4-5-चिकित्सा-पुनर्वास-गारंटी" aria-label="Permalink to &quot;4.5 चिकित्सा पुनर्वास गारंटी&quot;">​</a></h3><p>सहजीवी चिकित्सा प्रणाली साधकों को निःशुल्क मूल चिकित्सा और साधना-विचलन पुनर्वास सेवाएँ प्रदान करती है। साधना के दौरान चोट, विचलन-पागलपन, ऊर्जा विकार आदि स्थितियों में समय पर उपचार और पुनर्वास समर्थन मिलता है, यह सुनिश्चित करते हुए कि साधक दुर्घटनाओं के कारण विकास क्षमता न खोएँ।</p><h2 id="v-लक्षित-सहायता-के-उद्देश्य-और-विधियाँ" tabindex="-1">V. लक्षित सहायता के उद्देश्य और विधियाँ <a class="header-anchor" href="#v-लक्षित-सहायता-के-उद्देश्य-और-विधियाँ" aria-label="Permalink to &quot;V. लक्षित सहायता के उद्देश्य और विधियाँ&quot;">​</a></h2><p>लक्षित सहायता निम्नलिखित वंचित समूहों को संबोधित करती है:</p><ul><li><strong>निम्न-दान व्यक्ति</strong>: जन्मजात योग्यता में कमज़ोर, धीमी प्रगति वाले व्यक्तियों को अतिरिक्त संसाधन आवंटन और व्यक्तिगत मार्गदर्शन मिलता है</li><li><strong>निर्धन जातियाँ</strong>: समग्र संसाधन-वंचित, निम्न विकास स्तर वाली जातियों को जातीय विकास कोष से लक्षित समर्थन मिलता है</li><li><strong>आपदा-पीड़ित समूह</strong>: विमानीय आपदाओं, युद्धों आदि से घर और संसाधन खोने वाले समूहों को आपातकालीन राहत और पुनर्निर्माण समर्थन मिलता है</li><li><strong>विकलांग साधक</strong>: विभिन्न कारणों से शारीरिक या मानसिक विकलांगता वाले साधकों को विशेष साधना सहायक उपकरण और अनुकूलित साधना योजनाएँ मिलती हैं</li><li><strong>विचित्र जीवन</strong>: परंपरागत साधना प्रणालियों में न बैठने वाले विचित्र जीवनों को विशेष मूल्यांकन और अनुकूलित विकास पथ मिलते हैं</li></ul><p>लक्षित सहायता की विधियों में शामिल: अतिरिक्त संसाधन आवंटन, एक-से-एक गुरु मार्गदर्शन, अनुकूलित साधना योजनाएँ, विशेष उपकरण प्रावधान, अंतर-विमान आदान-प्रदान अवसर आदि। सहायता का लक्ष्य वंचित समूहों को मूल विकास स्तर तक पहुँचाना है, जिसके बाद वे धीरे-धीरे सामान्य अधिक परिश्रम-अधिक प्रतिफल वितरण प्रणाली में संक्रमण करें।</p><h2 id="vi-गारंटी-प्रणाली-के-धन-और-संसाधन-स्रोत" tabindex="-1">VI. गारंटी प्रणाली के धन और संसाधन स्रोत <a class="header-anchor" href="#vi-गारंटी-प्रणाली-के-धन-और-संसाधन-स्रोत" aria-label="Permalink to &quot;VI. गारंटी प्रणाली के धन और संसाधन स्रोत&quot;">​</a></h2><p>गारंटी प्रणाली के संचालन के लिए विशाल संसाधनों और धन की आवश्यकता है, जिनके स्रोत शामिल हैं:</p><ol><li><strong>सार्वजनिक संसाधन आय</strong>: सभ्यता द्वारा सीधे प्रबंधित सार्वजनिक आत्मा-नसों, ऊर्जा खनिज नसों, औषधि क्षेत्रों आदि की उपज</li><li><strong>योगदान-समायोजन कर</strong>: उच्च योगदानकर्ताओं पर एक निश्चित अनुपात का &quot;योगदान-समायोजन कर&quot; लगाया जाता है, जो गारंटी प्रणाली के संचालन हेतु उपयोग होता है (प्रगतिशील दर, अधिकतम 30% से अधिक नहीं)</li><li><strong>सभ्यता विकास कोष</strong>: लंगर जाल संचालन से उत्पन्न अधिशेष ऊर्जा, आंशिक रूप से सभ्यता विकास कोष में डाली जाती है</li><li><strong>प्रौद्योगिकी लाइसेंस आय</strong>: सभ्यता के स्वामित्व वाली नियम-अभियांत्रिकी प्रौद्योगिकियों के लाइसेंस शुल्क</li><li><strong>दान और वसीयत</strong>: व्यक्तियों और जातियों की स्वैच्छिक दान</li></ol><p>गारंटी प्रणाली की आय-व्यय का प्रबंधन दस हजार जातियों के गणराज्य सभा के अधीन गारंटी समिति करती है, खाते आवधिक रूप से सभी जीवनों के सामने सार्वजनिक होते हैं और निगरानी के अधीन रहते हैं।</p><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p>हर किसी के लिए पथ गारंटी प्रणाली लंगर सहजीवी सभ्यता की सामाजिक न्याय की आधारशिला है। यह सुनिश्चित करती है कि साधना और विकास-केंद्रित सभ्यता में, कोई भी जीवन उत्पत्ति, दान या निर्धनता के कारण विकास प्रणाली द्वारा त्यागा न जाए। हर किसी के लिए पथ समतावाद लाना नहीं, बल्कि हर जीवन को न्यायपूर्ण शुरुआत, ऊर्ध्वगामी माध्यम और न त्यागे जाने का वचन देना है। हर किसी के लिए पथ की गारंटी के तहत, हर जीवन अपना विकास पथ पा सकता है।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>06-多劳多得分配原理 (अधिक परिश्रम, अधिक प्रतिफल वितरण सिद्धांत)</li><li>07-自生自长进化法则 (स्व-विकास और स्व-संवर्धन का नियम)</li><li>38-共生医疗体系 (सहजीवी चिकित्सा प्रणाली)</li></ul>',43)])])}const c=a(i,[["render",d]]);export{p as __pageData,c as default};
